/**
 * Clip service worker.
 *
 * Precaches the whole build (list generated by scripts/generate-precache.mjs)
 * so the editor works with no network at all after the first visit. Nothing is
 * ever uploaded - the worker only serves local files.
 */
const VERSION_URL = '/precache-manifest.json'
let CACHE_NAME = 'clip-runtime'

async function precache() {
  const response = await fetch(VERSION_URL, { cache: 'no-cache' })
  // Clone before reading: the body can only be consumed once.
  const stored = response.clone()
  const manifest = await response.json()
  CACHE_NAME = `clip-${manifest.buildId}`
  const cache = await caches.open(CACHE_NAME)
  // Individual failures must not abort the install.
  await Promise.all(
    manifest.files.map((file) =>
      cache.add(new Request(file, { cache: 'reload' })).catch(() => {
        /* optional asset */
      }),
    ),
  )
  await cache.put(VERSION_URL, stored)
}

self.addEventListener('install', (event) => {
  event.waitUntil(precache().then(() => self.skipWaiting()))
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys()
      const manifest = await caches.match(VERSION_URL).then((r) => r?.json()).catch(() => null)
      const current = manifest ? `clip-${manifest.buildId}` : null
      await Promise.all(names.filter((n) => n.startsWith('clip-') && n !== current).map((n) => caches.delete(n)))
      await self.clients.claim()
    })(),
  )
})

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') void self.skipWaiting()
})

async function cacheFirst(request) {
  const cached = await caches.match(request, { ignoreSearch: true })
  if (cached) return cached
  const response = await fetch(request)
  if (response.ok && request.url.startsWith(self.location.origin)) {
    const cache = await caches.open(CACHE_NAME)
    void cache.put(request, response.clone())
  }
  return response
}

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET' || !request.url.startsWith(self.location.origin)) return

  // SPA navigations always resolve to the app shell.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(async () => (await caches.match('/index.html')) ?? (await caches.match('/')) ?? Response.error()),
    )
    return
  }
  event.respondWith(cacheFirst(request).catch(() => caches.match(request).then((r) => r ?? Response.error())))
})
